class Solution {
public:
    bool canAliceWin(int n) {
        int rem = n;
        int take = 10;
        bool alice_turn = true;
        while (rem >= take) {
            rem -= take;
            take--;
            alice_turn = !alice_turn;
        }
        return !alice_turn;
    }
};

